import{_ as i,o as a,c as o,a2 as n}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"ADR-0010 — Dettagli implementativi di disegni e canvas (M3)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0010-drawing-and-canvas-details.md","filePath":"adr/0010-drawing-and-canvas-details.md"}'),t={name:"adr/0010-drawing-and-canvas-details.md"};function d(c,e,r,s,l,g){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0010-—-dettagli-implementativi-di-disegni-e-canvas-m3" tabindex="-1">ADR-0010 — Dettagli implementativi di disegni e canvas (M3) <a class="header-anchor" href="#adr-0010-—-dettagli-implementativi-di-disegni-e-canvas-m3" aria-label="Permalink to &quot;ADR-0010 — Dettagli implementativi di disegni e canvas (M3)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.2.1, §2.4, §2.7.1, §2.7.2, §2.7.3, §3.4.6 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-24</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 (matrice funzioni), V-02/D-01, D-04, piano M3-WP1…WP4</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì, in modo puntuale (editor testo dei canvas, export, anteprime)</td></tr></tbody></table><p><strong>Aggiornamento 2026-11-15.</strong> <a href="./0054-editor-dei-disegni-merge-undo-ricarica-libreria-ricerca.html">ADR-0054</a> (proposta) emenda le decisioni 5, 6 e 7: le anteprime hanno una variante per tema (<code>&lt;hash&gt;.dark.svg</code>) e il binding <code>DrawingAPI.Preview</code> calcola l&#39;hash nel core al posto di <code>ReadPreview</code> (rimosso), la cache si pota all&#39;apertura del vault; la libreria di forme si fonde per id nella sync; la ricerca indicizza il testo come scritto dall&#39;utente e il TeX delle formule.</p><p><strong>Aggiornamento 2026-11-02.</strong> La versione <code>@excalidraw/excalidraw@0.18.1</code> è superata da ADR-0028 (alias <code>npm:@zsviczian/excalidraw@0.18.145</code>), e la rinomina riscrive ora anche i link dentro i disegni (ADR-0024, decisione 6); le regole offline restano quelle di questo ADR.</p><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>M3 porta in MemoBrain Notes i disegni Excalidraw (<code>.excalidraw</code>, JSON) e i canvas (<code>.canvas</code>, JSON Canvas 1.0), entrambi sincronizzati con la strategia per id già presente in <code>shared/go/merge</code>. Alcune scelte non erano fissate dal piano.</p><h2 id="decisioni" tabindex="-1">Decisioni <a class="header-anchor" href="#decisioni" aria-label="Permalink to &quot;Decisioni&quot;">​</a></h2><ol><li><strong>Excalidraw 0.18.1, caricato in lazy.</strong> <code>@excalidraw/excalidraw</code> è un chunk separato (<code>React.lazy</code> + <code>import()</code>), mai caricato all&#39;avvio. Gli asset (font, 13 MB) sono serviti dall&#39;app stessa (<code>/excalidraw-assets/</code>: middleware in <code>vite dev</code>, copia in <code>dist/</code> in <code>vite build</code>) e <code>window.EXCALIDRAW_ASSET_PATH</code> li indica prima del caricamento: nessuna richiesta di rete. Il gate è un test Playwright che fallisce a qualsiasi richiesta fuori dall&#39;origine dell&#39;app.</li><li><strong>Tipi di <code>@excalidraw/utils</code>.</strong> Il pacchetto non pubblica i tipi di <code>@excalidraw/utils/export</code>; <code>tsconfig.app.json</code> li mappa su <code>dist/types/utils/*</code> dentro <code>@excalidraw/excalidraw</code>, altrimenti <code>exportToSvg</code>/<code>exportToBlob</code> risultano non tipizzati.</li><li><strong>Autosave 2 s dei disegni, 1 s dei canvas</strong>, con lo stesso hook dei documenti (<code>useNoteDocument</code>, hash atteso e banner di conflitto). <code>onChange</code> di Excalidraw scatta anche per selezione e scroll: si salva solo se cambia la firma (id e versione degli elementi, numero di file).</li><li><strong>Esportazione nel vault, non su disco.</strong> Il webview Wails non garantisce il download via <code>&lt;a download&gt;</code> né l&#39;API File System Access. PNG (1×–3×, con o senza sfondo) e SVG vengono salvati accanto al disegno con <code>SaveAttachment</code>; &quot;copia&quot; usa <code>exportToClipboard</code>. Si può aggiungere un binding con finestra di salvataggio nativa in seguito.</li><li><strong>Anteprime SVG come <code>&lt;img&gt;</code> con URL blob.</strong> L&#39;SVG generato da <code>exportToSvg</code> è messo in cache per hash del contenuto (<code>.memobrain/cache/drawings/&lt;hash&gt;.svg</code>, mai sincronizzato) tramite <code>DrawingAPI</code>. Un&#39;immagine non esegue script né carica risorse e mantiene font e stili incorporati, cosa che la sanificazione DOMPurify dell&#39;SVG inline eliminerebbe. <code>SavePreview</code> valida hash (64 esadecimali, niente path), dimensione (4 MB) e contenuto (<code>&lt;svg</code>, niente <code>&lt;script</code>).</li><li><strong>Libreria Excalidraw nel vault</strong> (<code>.memobrain/excalidraw-library.json</code>, aggiunto all&#39;elenco dei file di configurazione ammessi): segue la sync dei file di impostazioni.</li><li><strong>Indicizzazione.</strong> <code>internal/drawing</code> e <code>internal/canvas</code> validano i file ed estraggono testo (FTS) e link (<code>[[…]]</code> sugli elementi/nel testo; i nodi file del canvas sono embed). Un file non valido resta elencato e cercabile per nome, con un avviso nel log. I link dei disegni e dei canvas alimentano backlink e grafo; il pannello Backlink li etichetta &quot;Disegno: X&quot; / &quot;Lavagna: X&quot; senza numero di riga. La <strong>rinomina con aggiornamento link riscrive solo le note <code>.md</code></strong>: i link dentro disegni e canvas non vengono riscritti (limite noto).</li><li><strong>Canvas: editor testuale semplice.</strong> Il piano prevede un mini editor CM6 per i nodi di testo; l&#39;implementazione usa una <code>&lt;textarea&gt;</code> in modifica e il Markdown renderizzato (stessa pipeline sanificata del reading view, con math ed embed) a riposo. È un compromesso di dimensione/rischio: CM6 richiederebbe il contesto Live Preview per ogni nodo. Sostituibile senza toccare il formato.</li><li><strong>Canvas: embed statico da dati.</strong> <code>![[mappa.canvas]]</code> si renderizza come SVG disegnato dai soli dati (<code>canvasSvg</code>, senza misure DOM), mostrato in <code>&lt;img&gt;</code>; doppio clic apre l&#39;editor.</li><li><strong>Merge.</strong> Nessuna modifica a <code>shared/go/merge</code>: le strategie <code>excalidraw-by-id</code> e <code>canvas-by-id</code> erano già attive in <code>sync/resolve.go</code>; M3-WP4 aggiunge i test e2e a due dispositivi (parti diverse convergono, versione più alta vince, un elemento cancellato resta cancellato, stesso nodo su entrambi i lati → copia di conflitto, nessuna perdita).</li></ol><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Nuova dipendenza <code>@excalidraw/excalidraw@0.18.1</code> (MIT).</li><li>Nuovo binding <code>DrawingAPI</code> (<code>ReadPreview</code>, <code>SavePreview</code>), nuovi pacchetti Go <code>internal/drawing</code> e <code>internal/canvas</code>, nuove directory frontend <code>drawing/</code> e <code>canvas/</code>.</li><li>Checklist manuale sul webview reale: <code>docs/qa/m3-drawings-canvas.md</code>.</li></ul>',10)])])}const v=i(t,[["render",d]]);export{p as __pageData,v as default};
